import {hazards,checkRoutes} from './core.js';
export function hideBasemapLabel(layer){return layer.type==='symbol'&&!/^(place_country|place_state|place_city_r)/.test(layer.id);}
export const project=([x,y])=>[-118.23+(x-400)*.00035,34.22-(y-220)*.00025];
export function overlayData(stage){return {hazards:{type:'FeatureCollection',features:hazards(stage).map(c=>({type:'Feature',properties:{},geometry:{type:'Polygon',coordinates:[Array.from({length:73},(_,i)=>project([c.x+Math.cos(i/72*Math.PI*2)*c.r,c.y+Math.sin(i/72*Math.PI*2)*c.r]))]}}))},routes:{type:'FeatureCollection',features:checkRoutes(stage).map(r=>({type:'Feature',properties:{id:r.id,blocked:r.blocked},geometry:{type:'LineString',coordinates:r.points.map(project)}}))}};}
let map,loaded=false,current={stage:0,layer:'all',selectedRoute:'B'};
export function updateMap(state){current=state;if(!loaded)return;const data=overlayData(state.stage);for(const key of ['hazards','routes'])map.getSource('pharos-'+key).setData(data[key]);for(const id of ['hazard-fill','hazard-core'])map.setLayoutProperty(id,'visibility',state.layer==='routes'?'none':'visible');for(const id of ['route-glow','route-line'])map.setLayoutProperty(id,'visibility',state.layer==='hazards'?'none':'visible');map.setPaintProperty('route-line','line-width',['case',['==',['get','id'],state.selectedRoute],3.5,2]);}
export function zoomMap(delta){if(map)map.easeTo({zoom:map.getZoom()+delta,duration:300});}
export function initializeMap(onRoute){if(!globalThis.maplibregl)return;try{map=new maplibregl.Map({container:'maplibre-canvas',style:'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',center:project([390,240]),zoom:13,pitch:0,attributionControl:{compact:true},maxZoom:17,minZoom:9});map.on('style.load',()=>{for(const layer of map.getStyle().layers){if(hideBasemapLabel(layer))map.setLayoutProperty(layer.id,'visibility','none');}const d=overlayData(current.stage);for(const key of ['hazards','routes'])map.addSource('pharos-'+key,{type:'geojson',data:d[key]});map.addLayer({id:'hazard-fill',type:'fill',source:'pharos-hazards',paint:{'fill-color':'#eb835d','fill-opacity':.13,'fill-antialias':true}});map.addLayer({id:'hazard-core',type:'fill',source:'pharos-hazards',paint:{'fill-color':'#e56d49','fill-opacity':.035}});for(const [id,width,opacity,blur] of [['route-glow',11,.12,5],['route-line',3,.85,0]])map.addLayer({id,type:'line',source:'pharos-routes',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':['case',['get','blocked'],'#cf876b','#9bc9b8'],'line-width':width,'line-opacity':opacity,'line-blur':blur}});map.addSource('pharos-points',{type:'geojson',data:{type:'FeatureCollection',features:[['OBSERVATION / 07',[450,215],'#f3946c'],['REVIEW ORIGIN',[350,270],'#b6ccc5'],['NORTH ASSEMBLY',[650,150],'#8baba0'],['SOUTH ASSEMBLY',[620,345],'#8baba0']].map(([label,p,color])=>({type:'Feature',properties:{label,color},geometry:{type:'Point',coordinates:project(p)}}))}});map.addLayer({id:'incident-points',type:'circle',source:'pharos-points',paint:{'circle-radius':4,'circle-color':['get','color'],'circle-stroke-width':4,'circle-stroke-color':'rgba(20,26,27,.7)'}});map.addLayer({id:'incident-labels',type:'symbol',source:'pharos-points',layout:{'text-field':['get','label'],'text-font':['Open Sans Regular'],'text-size':10,'text-offset':[0,1.5],'text-anchor':'top','text-letter-spacing':.12},paint:{'text-color':'#a3b4af','text-halo-color':'#111718','text-halo-width':2}});loaded=true;document.body.classList.remove('map-unavailable');document.body.classList.add('map-ready');updateMap(current);});map.on('click','route-line',e=>onRoute(e.features[0].properties.id));map.on('mouseenter','route-line',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','route-line',()=>map.getCanvas().style.cursor='');map.on('mousemove',e=>{const target=document.querySelector('#coordinates');if(target)target.textContent=`${e.lngLat.lat.toFixed(4)}° N  ${Math.abs(e.lngLat.lng).toFixed(4)}° W`;});map.on('error',()=>{if(!loaded)document.body.classList.add('map-unavailable');});}catch{document.body.classList.add('map-unavailable');}}
